import{_ as a,c as t,o as r,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"H2 — Improve loading and interaction","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/performance/02-improve.md","filePath":"practice/frontend/performance/02-improve.md"}'),o={name:"practice/frontend/performance/02-improve.md"};function i(s,e,d,c,l,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="h2-—-improve-loading-and-interaction" tabindex="-1">H2 — Improve loading and interaction <a class="header-anchor" href="#h2-—-improve-loading-and-interaction" aria-label="Permalink to “H2 — Improve loading and interaction”">​</a></h1><p><strong>Learner status: outstanding.</strong> Second required performance hometask. Prerequisites: H1 evidence and the applicable <a href="./../../../frontend/performance/">reading lessons</a>. Use the same artifact lineage, dataset and user journeys.</p><h2 id="goal" tabindex="-1"><span class="hub-section-number">1 </span>Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “1 Goal”">​</a></h2><p>Evaluate <strong>one loading intervention and one interaction intervention independently</strong>. Do not combine several fixes before measuring: you need to know which change caused the result. Keep a baseline variant and compare each intervention against it; then evaluate the combined accepted version in H3.</p><h2 id="part-a-choose-the-loading-cause-from-h1" tabindex="-1"><span class="hub-section-number">2 </span>Part A: choose the loading cause from H1 <a class="header-anchor" href="#part-a-choose-the-loading-cause-from-h1" aria-label="Permalink to “2 Part A: choose the loading cause from H1”">​</a></h2><table tabindex="0"><thead><tr><th>Observed cause</th><th>Candidate intervention</th><th>Required observations</th></tr></thead><tbody><tr><td>Hero discovered after JS/API</td><td>Declare appropriate image in HTML, or justify a matching preload</td><td>Initiator/start, LCP subparts and contention; no lazy hero</td></tr><tr><td>Oversized card/hero images</td><td>Generate responsive variants with correct <code>sizes</code>, formats and dimensions</td><td><code>currentSrc</code>, displayed/intrinsic size, DPR, bytes, quality and shifts</td></tr><tr><td>Font/CSS delays text</td><td>Reduce actual CSS/face/subset cost, improve discovery or compare display strategy</td><td>Readability, font bytes/requests, wrapping, CLS and no-JS/CSP behavior</td></tr><tr><td>Initial JS contains optional feature</td><td>Split at a feature/route boundary; correct excessive imports</td><td>Production graph, initial bytes, first feature-open cost, loading/error behavior</td></tr><tr><td>Repeated public asset fetch</td><td>Correct compression or explicit cache policy</td><td>Response headers, transferred/decoded size, cold and warm paths, freshness correctness</td></tr></tbody></table><p>Select one row justified by the trace. Use a bounded, targeted change. For images, verify fresh navigations at 320/768/1024/1920 CSS-pixel widths and at least one high-DPR condition. For fonts, test real supported accents and failed/delayed loading. For bundles, preserve required CSS/polyfills/registration; explain whether the saving came from deduplication, deep imports or ESM tree shaking.</p><p>A critical-CSS plugin, differential builds, a CDN deployment and a service worker are not mandatory. They are optional specialist exercises when they solve the chosen problem.</p><h2 id="part-b-choose-the-interaction-cause-from-h1" tabindex="-1"><span class="hub-section-number">3 </span>Part B: choose the interaction cause from H1 <a class="header-anchor" href="#part-b-choose-the-interaction-cause-from-h1" aria-label="Permalink to “3 Part B: choose the interaction cause from H1”">​</a></h2><p>Use an equivalent computation and output for the comparison. Choose one of these approaches based on the trace:</p><ul><li>Reduce algorithm/data work or bound/render fewer records when filtering or DOM volume dominates.</li><li>Yield between small tasks when a modest calculation can be divided safely.</li><li>Use a dedicated worker when expensive independent CPU work justifies startup/message costs.</li><li>Reduce forced synchronous layouts by changing read/write ordering.</li><li>Address demonstrated React component work with narrower state ownership or justified memoization after confirming correct identity.</li></ul><p>Keep controlled input updates immediate. Debounce may reduce requests but intentionally delays result start; it does not cancel in-flight work or remove stale-response races. A worker cannot manipulate DOM, and a service worker is not the default calculation abstraction. Compare input-to-feedback and total result completion; responsive feedback does not prove fast completion.</p><h2 id="verification-for-each-intervention" tabindex="-1"><span class="hub-section-number">4 </span>Verification for each intervention <a class="header-anchor" href="#verification-for-each-intervention" aria-label="Permalink to “4 Verification for each intervention”">​</a></h2><p>Repeat at least three matching before/after trials, adding more if noise makes the comparison uncertain. Save traces, raw data and a small diff for each experiment. Record what worsened as well as what improved: e.g. first feature-open latency or total compute time.</p><p>Keep the user-visible output equivalent. Check keyboard action/focus, no clipped or missing content, delayed/failed resources and navigation during pending work. For async/worker changes, replace queries rapidly so late work cannot overwrite current results; clean up owners on disposal. For code splitting, deliberately fail a chunk and observe bounded recovery. For images/fonts, retain readable content and reserved geometry while requests fail.</p><h2 id="acceptance-and-decision" tabindex="-1"><span class="hub-section-number">5 </span>Acceptance and decision <a class="header-anchor" href="#acceptance-and-decision" aria-label="Permalink to “5 Acceptance and decision”">​</a></h2><p>The report contains both categories, each with a causal explanation and reproducible comparison. Explain whether the measured change is large enough relative to run variation to support the conclusion. A plausible but ineffective intervention can be rejected and reverted; retain its report and explain the next hypothesis. Do not claim a saving from the source material as your measured result.</p><p>For accepted changes, summarize the user benefit, implementation cost, support limitations and remaining risks. Keep the working version ready for <a href="./03-verify.html">H3 — Verify and prevent regressions</a>.</p>',18)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
